algorithm:
OPENQASM 3.0;
include "stdgates.inc";
bit[4] c;
qubit[4] q;
// Prepare input state |1010> (Qiskit textbook QFT example input)
x q[0];
x q[2];
// 4-qubit Quantum Fourier Transform
// Canonical decomposition from Qiskit QFT(4, do_swaps=True):
// H + controlled-phase rotations cp(pi/2^k), then bit-reversal swaps.
h q[0];
cp(pi/2) q[1], q[0];
cp(pi/4) q[2], q[0];
cp(pi/8) q[3], q[0];
h q[1];
cp(pi/2) q[2], q[1];
cp(pi/4) q[3], q[1];
h q[2];
cp(pi/2) q[3], q[2];
h q[3];
// Bit-reversal swaps
swap q[0], q[3];
swap q[1], q[2];
c[0] = measure q[0];
c[1] = measure q[1];
c[2] = measure q[2];
c[3] = measure q[3];
